/* ============================================================
   PATCH 1.0.18 — поле ЧАСЫ в формате ЧЧ:ММ
   ============================================================ */
(function(){
'use strict';
if (window.__trkHoursV1018) return;
window.__trkHoursV1018 = true;

// === Парсинг: "8:15" / "08:15" / "815" / "8" / "8.25" (десятичное) ===
window._parseHoursInput = function(s) {
    s = String(s == null ? '' : s).trim().replace(',', '.');
    if (!s) return null;

    // "8:15" / "08:15"
    var m = s.match(/^(\d{1,2})\s*:\s*(\d{1,2})$/);
    if (m) {
        var h1 = parseInt(m[1], 10) || 0;
        var mm1 = parseInt(m[2], 10) || 0;
        if (mm1 > 59) mm1 = 59;
        if (h1 > 24) h1 = 24;
        if (h1 === 24) mm1 = 0;
        return Math.round((h1 + mm1 / 60) * 100) / 100;
    }

    // "815" / "0815" (4 цифры = ЧЧММ)
    if (/^\d{4}$/.test(s)) {
        var hh2 = parseInt(s.slice(0, 2), 10) || 0;
        var mm2 = parseInt(s.slice(2), 10) || 0;
        if (mm2 > 59) mm2 = 59;
        if (hh2 > 24) hh2 = 24;
        if (hh2 === 24) mm2 = 0;
        return Math.round((hh2 + mm2 / 60) * 100) / 100;
    }

    // "815" (3 цифры) — трактуем как "8:15"
    if (/^\d{3}$/.test(s)) {
        var hh3 = parseInt(s[0], 10) || 0;
        var mm3 = parseInt(s.slice(1), 10) || 0;
        if (mm3 > 59) mm3 = 59;
        return Math.round((hh3 + mm3 / 60) * 100) / 100;
    }

    // "8" / "15" (1-2 цифры) — это часы
    if (/^\d{1,2}$/.test(s)) {
        var hh4 = parseInt(s, 10) || 0;
        if (hh4 > 24) hh4 = 24;
        return hh4;
    }

    // Fallback: десятичное "8.25"
    var n = parseFloat(s);
    if (isNaN(n)) return null;
    if (n < 0) n = 0;
    if (n > 24) n = 24;
    return n;
};

// === Формат: всегда "ЧЧ:ММ", clamp [0; 24] ===
window._formatHoursInput = function(h) {
    h = Number(h) || 0;
    if (h < 0) h = 0;
    if (h >= 24) return '24:00';
    var totalMin = Math.round(h * 60);
    if (totalMin >= 24 * 60) return '24:00';
    var hh = Math.floor(totalMin / 60);
    var mm = totalMin - hh * 60;
    return (hh < 10 ? '0' : '') + hh + ':' + (mm < 10 ? '0' : '') + mm;
};

// === Маска ввода ===
function _attachMask(el){
    if (!el || el._hoursMaskV1018) return;
    el._hoursMaskV1018 = true;

    el.addEventListener('input', function(){
        var v = this.value;
        // . , → :
        v = v.replace(/[.,]/g, ':');
        // Только цифры и :
        v = v.replace(/[^\d:]/g, '');
        // Оставить только первое двоеточие
        var idx = v.indexOf(':');
        if (idx !== -1) {
            v = v.slice(0, idx + 1) + v.slice(idx + 1).replace(/:/g, '');
        }
        // Не больше 5 символов (ЧЧ:ММ)
        if (v.length > 5) v = v.slice(0, 5);
        if (this.value !== v) this.value = v;
    });

    el.addEventListener('blur', function(){
        var v = window._parseHoursInput(this.value);
        if (v !== null && !isNaN(v)) {
            this.value = window._formatHoursInput(v);
        }
    });

    el.addEventListener('keydown', function(e){
        if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
            e.preventDefault();
            var v = window._parseHoursInput(this.value);
            if (v === null || isNaN(v)) v = 0;
            var step = e.shiftKey ? 1 : 0.25;
            if (e.key === 'ArrowDown') step = -step;
            v = Math.max(0, Math.min(24, v + step));
            this.value = window._formatHoursInput(v);
            try { this.dispatchEvent(new Event('input', {bubbles: true})); } catch(err){}
        }
    });
}

// === Навесить на существующее поле + на все переоткрытия модалки ===
function _attachToLogHours(){
    var el = document.getElementById('log_hours');
    if (el) {
        _attachMask(el);
        // Если поле пустое (например, из-за кэшированного HTML) — поставим дефолт
        if (!el.value) el.value = '08:00';
    }
}
_attachToLogHours();
setTimeout(_attachToLogHours, 300);
setTimeout(_attachToLogHours, 1000);

// Наблюдатель на logModal — если HTML был заменён рендером
(function _obs(){
    var lm = document.getElementById('logModal');
    if (!lm || lm._hoursObsV1018) return;
    lm._hoursObsV1018 = true;
    new MutationObserver(function(){
        if (lm.classList.contains('active')) _attachToLogHours();
    }).observe(lm, { attributes: true, attributeFilter: ['class'] });
})();

})();

/* ============================================================
   PATCH 1.0.18 — поле ЧАСЫ в формате ЧЧ:ММ
   ============================================================ */
#logModal #log_hours,
#log_hours {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace !important;
    text-align: center !important;
    letter-spacing: 1px !important;
    font-variant-numeric: tabular-nums;
}
#logModal #log_hours::placeholder {
    letter-spacing: 0.5px;
    opacity: 0.55;
}
